import{_ as l,C as a,o as n,c as o,E as t,a2 as s}from"./chunks/framework.mq20U3A6.js";const b=JSON.parse('{"title":"预留一百，结算一百三十：共享词元账本限制了什么","description":"","frontmatter":{"title":"预留一百，结算一百三十：共享词元账本限制了什么","date":"2026-10-25","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"共享输出词元账本约束的是预留还是实际供应方输出，它如何暴露超额？","summary":"七项局部账本检查区分预留互斥、实际结算和供应方服从，不能据此推导多智能体架构的普遍优劣。","sources":"https://arxiv.org/html/2610.27655v1; https://github.com/ethanyyang/agent-scaling-dual-control","pageClass":"runtime-v6-article","item_id":"SIG-20261025-003","lifecycle":"Published","cover":"/assets/covers/daily-2026-10-25-sig-20261025-003-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"zh/engineering/2026-10-25-sig-20261025-003.md","filePath":"zh/engineering/2026-10-25-sig-20261025-003.md","lastUpdated":null}'),c={name:"zh/engineering/2026-10-25-sig-20261025-003.md"};function p(h,e,d,g,u,_){const r=a("ArticleCover"),i=a("ArticleTableScroll");return n(),o("div",null,[t(r,{image:"/assets/covers/daily-2026-10-25-sig-20261025-003-cover.png",kicker:"研究成果",title:"预留一百，结算一百三十：共享词元账本限制了什么",summary:"七项局部账本检查区分预留互斥、实际结算和供应方服从，不能据此推导多智能体架构的普遍优劣。",version:"2026-10-25",languageHref:"/en/engineering/2026-10-25-sig-20261025-003",languageLabel:"English"}),t(i,{language:"zh"}),e[0]||(e[0]=s('<h1 id="预留一百-结算一百三十-共享词元账本限制了什么" tabindex="-1">预留一百，结算一百三十：共享词元账本限制了什么 <a class="header-anchor" href="#预留一百-结算一百三十-共享词元账本限制了什么" aria-label="Permalink to &quot;预留一百，结算一百三十：共享词元账本限制了什么&quot;">​</a></h1><p>预留额度被限制在 100，随后提交的实际用量却可以是 130；账本接受结算，并记录超额 30。这是本日内部源码实验中的合成用量场景，不是一次真实供应方超限事件。它提出了预算评估中容易被混为一谈的两个问题：系统准许预留多少，与供应方最终产生多少，是否由同一机制控制？</p><p>在本次执行的账本接口上，答案是否定的。预留限制与实际输出上限是两个机制。账本能够约束共享预留并如实记下超额，不能靠记账本身使外部供应方服从请求上限。</p><h2 id="从申请额度到结算实际用量" tabindex="-1">从申请额度到结算实际用量 <a class="header-anchor" href="#从申请额度到结算实际用量" aria-label="Permalink to &quot;从申请额度到结算实际用量&quot;">​</a></h2><p>本次分析使用已读取并固定内容哈希的完整 111 行账本模块。代码为预留操作使用同一把锁，按供应方报告的实际用量结算，释放失败调用的预留，并记录超额。模块来源是多智能体预算比较研究的公开代码。[1][2]</p><p>内部探针在本地 Python（编程语言）3.13.15 环境执行，预期结果在执行前写入脚本。本日七项检查覆盖了以下不同职责：[3]</p><ul><li>顺序申请 80、80，在总额 100 下分别获得 80、20。</li><li>额度用尽后再申请 1，被拒绝。</li><li>释放 20、结算实际用量 50 后，记录为已花费 50、预留 0、剩余 50、超额 0。</li><li>预留 100 后提交合成实际用量 130，记录为已花费 130、预留 0、剩余 0、已耗尽、超额 30。</li><li>缺少用量数据时拒绝处理；另一项检查识别输出词元计数字段的别名。</li><li>八个线程各申请 30、总额为 100，连续 20 轮的预留总额均为 100。</li></ul><p>七项检查中，缺失用量和计数字段别名分别计一项。并发部分表明这些实际调度下未发生预留超额，不是对一切线程交错的证明。超额场景中的 130 是人为输入，不能用于估计供应方超额频率。[3]</p><h2 id="不再分配-与-已经产生-属于不同时间点" tabindex="-1">“不再分配”与“已经产生”属于不同时间点 <a class="header-anchor" href="#不再分配-与-已经产生-属于不同时间点" aria-label="Permalink to &quot;“不再分配”与“已经产生”属于不同时间点&quot;">​</a></h2><p>账本拒绝后续预留，可以避免继续承诺额度；这不等于能够收回已产生的输出。接受实际用量 130 并记录超额，反而保留了实际花费的可见性。把它简单标为“预算失效”，会丢掉预留控制有效这一部分证据；把预留测试通过写成“端到端硬上限”，又会越过探针边界。</p><p>我们的解释是，预算比较应分别检查预留互斥、发给供应方的请求上限、供应方返回的实际用量、超额处置，以及实验中各架构是否按设计执行。本次只直接执行了局部账本，没有模型调用、供应方路由或完整任务轨迹。</p><p>对象一致性也不能用记账代替。研究对象中的另一类检查，比较的是已发出与实际执行的写操作；这与词元账本分属不同对象。记录差异是否阻止执行，需要检查相应路径，不能从“有记录”推导“有拦截”。[1][2]</p><h2 id="论文结果为何不能直接变成架构排名" tabindex="-1">论文结果为何不能直接变成架构排名 <a class="header-anchor" href="#论文结果为何不能直接变成架构排名" aria-label="Permalink to &quot;论文结果为何不能直接变成架构排名&quot;">​</a></h2><p>原研究作者报告，所有实验单元都没有达到预注册的 90% 按指令写入保真度门槛，严格审计为 680/2744，约 25%。因此，机械有效的单元不能直接称为架构保真度有效。[1，第 4.1 节、表 6]</p><p>作者还报告第二种模拟器下某个近阈值单元有正收益；模拟器间变化的区间跨零，且没有多重比较校正。这构成对“任何条件下都无收益”的限制，不支持另一个普遍结论。能力斜率区间宽，不能把不显著解释成没有关系；耗尽场景占损失较多是描述性分解，不能据此指定因果来源。[1，第 4.3–4.6 节]</p><p>这些限制并不否定账本局部实验的用途。它们限定了用途：解释预算接口的职责，而非复现多智能体准确率、解释论文损失或排序所有智能体架构。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><p>源码事实说明模块中的机制；作者报告保留作者的实验范围；本次内部实验仅说明本地合成输入和并发探针的结果。未建立独立第三方对同一主张的复现，内部证据不能改称独立验证。发表、引用、评审均不自动建立正确性，实现成功也不能推出普遍有效性。</p><ol><li><a href="https://arxiv.org/html/2610.27655v1" target="_blank" rel="noreferrer">多智能体预算比较研究，版本 1</a>，研究作者，研究论文；采用本日已读版本，重点为第 4.1、4.3–4.6 节。保真度、模拟器和统计结论均为作者报告。</li><li><a href="https://github.com/ethanyyang/agent-scaling-dual-control" target="_blank" rel="noreferrer">研究配套公开代码</a>，项目维护者，代码；本日读取的 <code>completion_budget.py</code>（输出词元预算模块文件），共 111 行。内容哈希固定本地提取，未确认其与论文评测部署对应的不可变提交。</li><li>本日分析阶段内部账本探针，包含原始模块、七项检查、20 轮并发输出、执行记录与源码内容哈希，随研究对象保存。未运行模型或基准测试。</li></ol><h2 id="缺少的仍是完整调用链证据" tabindex="-1">缺少的仍是完整调用链证据 <a class="header-anchor" href="#缺少的仍是完整调用链证据" aria-label="Permalink to &quot;缺少的仍是完整调用链证据&quot;">​</a></h2><p>下一项需要检验的是：完整调用路径在供应方忽略请求上限时如何处理，以及超额怎样进入预算配对与有效性筛选。原研究修正工具模式可见性后只进行了小规模检查，没有重跑完整网格；正文与方法中对该检查的任务描述也不一致，不能悄悄拼成完整复验。[1]</p><p>在这些证据补齐以前，可以保留账本已展示的预留控制与超额记账能力；对供应方服从、架构保真度和比较结果，应继续分别判断。</p>',22))])}const f=l(c,[["render",p]]);export{b as __pageData,f as default};
